<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تغییر رمز | رستوران</title><link rel="stylesheet" href="/assets/style.css"></head><body class="auth"><form class="card auth-card" method="post"><div class="auth-brand"><div class="auth-logo">🔑</div><h1>تعیین رمز جدید</h1><p>رمز جدید خود را انتخاب کنید.</p></div><?php if(!empty($error)): ?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif; ?><?php if(!empty($message)): ?><div class="alert success"><?=htmlspecialchars($message)?></div><div class="auth-hint"><a href="/?page=login">ورود به سامانه</a></div><?php elseif($valid): ?><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><label>رمز جدید<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><label>تکرار رمز جدید<input name="password_confirmation" type="password" minlength="8" autocomplete="new-password" required></label><button class="primary" type="submit">ذخیره رمز جدید</button><?php endif; ?></form></body></html>